/* 
  GraphQL Subscription Example 
*/

subscription OnNewMessageReceived($roomId: ID!) {
  # This block will execute and push data to the client 
  # EVERY TIME a new message is added to this room!
  messageAdded(roomId: $roomId) {
    id
    text
    sender {
      username
    }
    timestamp
  }
}

